package com.yuegang.zhihui.inventory.application;import com.yuegang.zhihui.inventory.api.InventoryReconciliationView;import java.time.ZoneOffset;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;public final class InventoryMaintenanceService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public InventoryMaintenanceService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public int releaseExpired(){List<Row>rows=jdbc.query("SELECT request_id,sku_id,quantity,reference_type,reference_id FROM inventory_reservation WHERE status='LOCKED' AND expires_at<NOW(6) LIMIT 100",(r,n)->new Row(r.getString(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5)));int released=0;for(Row row:rows){Boolean done=tx.execute(s->{if(jdbc.update("UPDATE inventory_reservation SET status='RELEASED',version=version+1 WHERE request_id=? AND status='LOCKED'",row.request())!=1)return false;jdbc.update("UPDATE inventory_stock SET available_quantity=available_quantity+?,locked_quantity=locked_quantity-?,version=version+1 WHERE sku_id=? AND locked_quantity>=?",row.quantity(),row.quantity(),row.sku(),row.quantity());jdbc.update("INSERT IGNORE INTO inventory_ledger(id,sku_id,movement_type,available_delta,locked_delta,sold_delta,reference_type,reference_id,request_id) VALUES(?,?, 'TIMEOUT_RELEASE',?, ?,0,?,?,?)",next(),row.sku(),row.quantity(),-row.quantity(),row.referenceType(),row.referenceId(),row.request());return true;});if(Boolean.TRUE.equals(done))released++;}return released;}public List<InventoryReconciliationView>reconcile(){List<Long>skus=jdbc.queryForList("SELECT sku_id FROM inventory_stock ORDER BY sku_id",Long.class);List<InventoryReconciliationView>out=new ArrayList<>();for(long sku:skus){long actual=jdbc.queryForObject("SELECT available_quantity FROM inventory_stock WHERE sku_id=?",Long.class,sku);Long expected=jdbc.queryForObject("SELECT COALESCE(SUM(available_delta),0) FROM inventory_ledger WHERE sku_id=?",Long.class,sku);long difference=actual-Objects.requireNonNullElse(expected,0L),id=next();String status=difference==0?"MATCHED":"MISMATCH";jdbc.update("INSERT INTO inventory_reconciliation(id,sku_id,expected_available,actual_available,difference_quantity,status,checked_at) VALUES(?,?,?,?,?,?,NOW(6))",id,sku,expected,actual,difference,status);out.add(new InventoryReconciliationView(Long.toString(id),Long.toString(sku),expected,actual,difference,status,java.time.OffsetDateTime.now(ZoneOffset.UTC)));}return out;}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private record Row(String request,long sku,long quantity,String referenceType,String referenceId){}}
